 try{data=await catalog({repair:false});keys=new Set((await(await caches.open(UNITS)).keys()).map(request=>request.url));}
 catch{return {type:'LESSON_STATUS',build:BUILD,pending:true,shellReady:false,error:'Local inventory unavailable'};}
