// Fail closed for old, hidden/unresponsive or concurrently opening clients.
async function compatibleCompressionWindows(){
 const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});
 const scoped=windows.filter(client=>client.url.startsWith(self.registration.scope));
 if(!scoped.length||downloadJobs.size)return false;
 const answers=await Promise.all(scoped.map(client=>new Promise(resolve=>{
  const channel=new MessageChannel();let done=false;const finish=value=>{if(done)return;done=true;clearTimeout(timer);channel.port1.close();resolve(value);};const timer=setTimeout(()=>finish(false),4000);
  channel.port1.onmessage=({data})=>finish(data?.build===BUILD&&data?.variants===1);
  try{client.postMessage({type:'GRE_COMPRESSION_CAPABILITY',build:BUILD},[channel.port2]);}catch{finish(false);}
 })));
 const after=(await self.clients.matchAll({type:'window',includeUncontrolled:true})).filter(client=>client.url.startsWith(self.registration.scope));
 return answers.every(Boolean)&&!downloadJobs.size&&scoped.map(c=>c.id).sort().join('|')===after.map(c=>c.id).sort().join('|');
}
